        'crowd_mix', jsonb_build_object('status','women_reader_craft_beer_creative_couple_queer_friendly_and_mainstream_local_mix_without_lgbtq_majority','source_urls',to_jsonb(array['https://www.elespectador.com/el-magazin-cultural/daniela-villamizar-la-mujer-que-quiso-devolverle-la-feminidad-a-la-cerveza/','https://www.lafm.com.co/sociedad/matorral-libros-y-cerveza-en-un-rincon-unico-de-bogota-358080','https://visitbogota.co/sites/default/files/2026-06/Gu%C3%ADa%20LGBTI%20Digital%20ok.pdf']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','informal_cafe_date_outdoor_and_cool_evening_context_without_door_selection','source_urls',to_jsonb(array['https://es.restaurantguru.com/Diosa-Cerveceria-Bogota','https://www.elespectador.com/el-magazin-cultural/daniela-villamizar-la-mujer-que-quiso-devolverle-la-feminidad-a-la-cerveza/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
