        'best_nights', jsonb_build_object('status','friday_saturday_multiroom_salsa_merengue_electronic_reggaeton_soul_disco_funk_and_variable_thursday','source_urls',to_jsonb(array['https://wanderlog.com/place/details/978671/disco-jaguar','https://es.restaurantguru.com/Disco-Jaguar-Bogota','https://revistadc.com/wp-content/uploads/2026/03/MAPA-BOGOTA-FEBRERO-web.pdf']::text[]),'checked_at','2026-08-06T00:00:00Z'),
