        'dress_code', jsonb_build_object('status','polished_multiroom_smart_casual_context_without_reliable_published_code','source_urls',to_jsonb(array['https://wanderlog.com/place/details/978671/disco-jaguar','https://es.restaurantguru.com/Disco-Jaguar-Bogota']::text[]),'checked_at','2026-08-06T00:00:00Z'),
