        'best_nights', jsonb_build_object('status','recurring_wednesday_electronic_thursday_local_energy_and_lineup_led_weekend_pattern','source_urls',to_jsonb(array['https://wanderlog.com/es/place/details/1826714/el-coq','https://co.iqos.com/es/noticias/vida-nocturna-bogota-el-coq-bogota','https://observatorio.desarrolloeconomico.gov.co/wp-content/uploads/2025/03/cuaderno40.pdf']::text[]),'checked_at','2026-08-06T00:00:00Z'),
