    (587::bigint, jsonb_build_object(
      'queue_wait', 'Circuit-scale nights can produce a real line and costly cover; quieter editions move faster. Reviews include efficient entry, a denied-admission complaint and a disputed 120,000 COP charge. Buy through the official event link, save the terms and arrive before the headline set.',
      'best_nights', 'Friday and Saturday are the main play, especially when the rooftop and a named circuit event are active. This is polished, high-energy El Mozo—not the old neighbourhood-bar portrait some guides copy. Follow the current flyer for music, hosts and venue because the brand has used more than one address.',
      'crowd_mix', 'Gay men are the visible centre, joined by circuit regulars, polished Zona Rosa groups, queer friends and international party travellers. Locals give the room its social code, but big events draw more visitors than a Chapinero beer bar. Expect a dressier, more male and image-aware crowd.',
      'dress_code', 'Lean polished and party-ready: fitted separates, fashion sneakers, clubwear or a sharper circuit look. The terrace rewards a layer for Bogotá’s cold air; the dance floor needs breathable fabric. No stable written code was found, and one guest reports rude refusal, so confirm themed requirements and keep a backup.',
      'staff_inclusivity', 'Recent reviews praise the design, shows, atmosphere and fast service; the venue also has historic public recognition for anti-discrimination values. That sits beside a denied-entry complaint and disputed-cover refund request. Inclusion must be judged at today’s door, with pricing shown clearly.',
      'venue_classification', 'active_zona_rosa_gay_male_led_rooftop_and_circuit_club_with_polished_local_traveller_crowd_strong_show_design_praise_and_material_door_cover_transparency_concerns',
      'identity_note', 'Current venue evidence places El Mozo at Avenida Calle 85 #12-51. Some current guides still conflate it with an older Chapinero address, so event posts should control routing.',
      'source_urls', to_jsonb(array['https://www.instagram.com/elmozocolombia1/','https://wanderlog.com/place/details/978673/el-mozo-club','https://www.gayout.com/south-america/colombia/bogota/bars/el-mozo-bogota','https://historico.participacionbogota.gov.co/el-mozo-primer-establecimiento-publico-libre-de-discriminacion-en-bogota','https://www.gaytravel4u.es/event/el-mozo-circuit-events-bogota/','https://visitbogota.co/sites/default/files/2026-06/Gu%C3%ADa%20LGBTI%20Digital%20ok.pdf']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','circuit_event_line_cover_efficiency_denial_and_disputed_charge_reports_with_official_ticket_guidance','source_urls',to_jsonb(array['https://wanderlog.com/place/details/978673/el-mozo-club','https://www.gayout.com/south-america/colombia/bogota/bars/el-mozo-bogota','https://www.gaytravel4u.es/event/el-mozo-circuit-events-bogota/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','friday_saturday_rooftop_named_circuit_event_and_current_flyer_led_identity','source_urls',to_jsonb(array['https://www.instagram.com/elmozocolombia1/','https://wanderlog.com/place/details/978673/el-mozo-club','https://www.gaytravel4u.es/event/el-mozo-circuit-events-bogota/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','gay_male_circuit_polished_zona_rosa_local_queer_friend_and_international_party_traveller_mix','source_urls',to_jsonb(array['https://wanderlog.com/place/details/978673/el-mozo-club','https://www.gaytravel4u.es/event/el-mozo-circuit-events-bogota/','https://visitbogota.co/sites/default/files/2026-06/Gu%C3%ADa%20LGBTI%20Digital%20ok.pdf']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','polished_circuit_rooftop_cold_air_dance_floor_and_unclear_door_code_context','source_urls',to_jsonb(array['https://wanderlog.com/place/details/978673/el-mozo-club','https://www.gaytravel4u.es/event/el-mozo-circuit-events-bogota/']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','current_design_show_atmosphere_service_praise_and_historic_anti_discrimination_recognition_balanced_against_door_cover_reports','source_urls',to_jsonb(array['https://wanderlog.com/place/details/978673/el-mozo-club','https://www.gayout.com/south-america/colombia/bogota/bars/el-mozo-bogota','https://historico.participacionbogota.gov.co/el-mozo-primer-establecimiento-publico-libre-de-discriminacion-en-bogota']::text[]),'checked_at','2026-08-06T00:00:00Z')
