    (1196::bigint, jsonb_build_object(
      'queue_wait', 'The room is intimate and usually works as a first stop rather than a queue marathon. Arrive before the live drag on Wednesday or karaoke on Thursday if you want a seat and an easy song request; later, groups spill in before larger clubs. Confirm opening on the day because published weekly hours do not agree.',
      'best_nights', 'Wednesday brings live drag; Thursday turns the old romantic videos into communal karaoke. Friday and Saturday are best for the full nostalgic singalong before crossing to a bigger dance floor. Come for boleros, Latin heartbreak and memory—not current-chart club music. The songs, more than the clock, run the room.',
      'crowd_mix', 'Queer Bogotanos, gay men across generations, drag regulars, couples, friend groups and curious visitors share a proudly sentimental local bar. Tourists arrive because of its history and proximity to bigger clubs, yet Spanish-language songs keep the centre of gravity unmistakably Colombian and neighbourhood-led.',
      'dress_code', 'Wear what lets you sing: relaxed jeans, a date-night shirt, vintage colour or camp romantic detail. There is no known fashion door, and the kitsch, memory-covered room rewards personality over polish. Bogotá gets cold after midnight, so bring a layer for the walk between bars and keep your phone tucked away outside.',
      'staff_inclusivity', 'Local storytelling and many guest accounts describe a warm gay institution built around songs and shared memories. A serious 2026 review alleges theft and drug dealing; that is not proven fact, but cannot be ignored. Watch your drink and belongings, stay with friends and report concerns immediately.',
      'venue_classification', 'active_historic_bogota_gay_video_singalong_drag_and_karaoke_bar_with_multigenerational_local_crowd_warm_community_identity_and_material_current_safety_allegation',
      'source_urls', to_jsonb(array['https://wanderlog.com/place/details/6062060/the-dog-and-the-calandria','https://es.travelgay.com/venue/el-perro-y-la-calandria-bogota','https://www.tripadvisor.ca/Attraction_Review-g294074-d10036093-Reviews-El_Perro_y_la_Calandria-Bogota.html','https://es.restaurantguru.com/El-Perro-Y-La-Calandria-Bogota','https://www.sudakas.co/post/el-perro-y-la-calandria-el-bar-bogotano-que-colecciona-recuerdos-escondidos-en-canciones']::text[]),
      'topic_evidence', jsonb_build_object(
        'queue_wait', jsonb_build_object('status','intimate_first_stop_early_seating_drag_karaoke_song_request_and_conflicting_hours_context','source_urls',to_jsonb(array['https://wanderlog.com/place/details/6062060/the-dog-and-the-calandria','https://es.travelgay.com/venue/el-perro-y-la-calandria-bogota','https://www.tripadvisor.ca/Attraction_Review-g294074-d10036093-Reviews-El_Perro_y_la_Calandria-Bogota.html']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'best_nights', jsonb_build_object('status','wednesday_live_drag_thursday_karaoke_weekend_warmup_and_romantic_latin_singalong_identity','source_urls',to_jsonb(array['https://wanderlog.com/place/details/6062060/the-dog-and-the-calandria','https://www.sudakas.co/post/el-perro-y-la-calandria-el-bar-bogotano-que-colecciona-recuerdos-escondidos-en-canciones','https://es.travelgay.com/venue/el-perro-y-la-calandria-bogota']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'crowd_mix', jsonb_build_object('status','multigenerational_queer_bogotano_gay_drag_couple_friend_and_curious_visitor_mix_with_local_song_centre','source_urls',to_jsonb(array['https://www.sudakas.co/post/el-perro-y-la-calandria-el-bar-bogotano-que-colecciona-recuerdos-escondidos-en-canciones','https://wanderlog.com/place/details/6062060/the-dog-and-the-calandria','https://www.tripadvisor.ca/Attraction_Review-g294074-d10036093-Reviews-El_Perro_y_la_Calandria-Bogota.html']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'dress_code', jsonb_build_object('status','informal_kitsch_romantic_singalong_and_cold_late_bogota_context_without_fashion_door','source_urls',to_jsonb(array['https://www.sudakas.co/post/el-perro-y-la-calandria-el-bar-bogotano-que-colecciona-recuerdos-escondidos-en-canciones','https://es.travelgay.com/venue/el-perro-y-la-calandria-bogota']::text[]),'checked_at','2026-08-06T00:00:00Z'),
        'staff_inclusivity', jsonb_build_object('status','strong_warm_affectionate_community_identity_balanced_against_single_material_2026_theft_and_drug_allegation','source_urls',to_jsonb(array['https://www.sudakas.co/post/el-perro-y-la-calandria-el-bar-bogotano-que-colecciona-recuerdos-escondidos-en-canciones','https://wanderlog.com/place/details/6062060/the-dog-and-the-calandria','https://es.restaurantguru.com/El-Perro-Y-La-Calandria-Bogota']::text[]),'checked_at','2026-08-06T00:00:00Z')
